function nextIndex(key,current,length){if(key==='Home')return 0;if(key==='End')return length-1;if(key==='ArrowRight'||key==='ArrowDown')return(current+1)%length;if(key==='ArrowLeft'||key==='ArrowUp')return(current+length-1)%length;return current;}
function motionAllowed(manualOff,systemReduce){return !manualOff&&!systemReduce;}
function selectChapter(items,line){let selected=items[0]?.id||'top';for(const item of items){if(item.top<=line)selected=item.id;}return selected;}
