function animatePanel(){if(!motionAllowed(manualOff,media.matches)||!$('phase-panel').animate)return;$('phase-panel').getAnimations().forEach(a=>a.cancel());$('phase-panel').animate([{opacity:.35,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.2,.7,.2,1)'});}
function render(announce=false){const p=projects[caseIndex],phase=phaseByCase[caseIndex],stage=p.stages[phase];text('explorer-title',p.title[lang]);text('case-context',p.context[lang]);text('phase-caption',phaseLabels[lang][phase]);text('phase-heading',stage.title[lang]);text('phase-copy',stage.copy[lang]);['map-start','map-middle','map-end'].forEach((id,i)=>{text(id,p.map[lang][i]);$(id).classList.toggle('map-active',i===phase);});caseButtons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===caseIndex));b.tabIndex=i===caseIndex?0:-1;});phaseButtons.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===phase));b.tabIndex=i===phase?0:-1;});$('case-panel').setAttribute('aria-labelledby','case-tab-'+caseIndex);$('phase-panel').setAttribute('aria-labelledby','phase-tab-'+phase);$('case-detail-link').setAttribute('href','#'+p.id);text('next-step',lang?(phase<2?'Next: '+phaseLabels[1][phase+1]+' →':'Back to the challenge ↺'):(phase<2?'下一步：'+phaseLabels[0][phase+1]+' →':'回看问题 ↺'));if(announce){text('explorer-announcement',p.title[lang]+' / '+phaseLabels[lang][phase]);animatePanel();}}
function bindTabs(buttons,select){buttons.forEach((button,index)=>{button.addEventListener('click',()=>select(index));button.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const next=nextIndex(e.key,index,buttons.length);select(next);buttons[next].focus();});});}
bindTabs(caseButtons,i=>{caseIndex=i;render(true);});bindTabs(phaseButtons,i=>{phaseByCase[caseIndex]=i;render(true);});$('next-step').addEventListener('click',()=>{phaseByCase[caseIndex]=(phaseByCase[caseIndex]+1)%3;render(true);});
