dialog.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{const destination=doc.querySelector(a.hash);if(destination instanceof HTMLDetailsElement)destination.open=true;returnFocus=null;closeOverview();requestAnimationFrame(()=>{destination?.querySelector('summary')?.focus();destination?.scrollIntoView({block:'start',behavior:motionAllowed(manualOff,media.matches)?'smooth':'auto'});});}));
const entries=[...doc.querySelectorAll('.career-entry')],expandButton=$('expand-career');
function updateExpand(){const all=entries.every(d=>d.open);expandButton.textContent=lang?(all?'Collapse all':'Expand all'):(all?'收起全部':'展开全部');expandButton.setAttribute('aria-expanded',String(all));}
expandButton.addEventListener('click',()=>{const next=!entries.every(d=>d.open);entries.forEach(d=>{d.open=next;});updateExpand();});entries.forEach(d=>d.addEventListener('toggle',updateExpand));
const sections=[...doc.querySelectorAll('main > section[id]')],chapterNames={top:['开篇','Introduction'],work:['项目探索','Project explorer'],experience:['完整履历','Experience'],creative:['工作之外','Beyond work']};let frame=0;
function updateReading(){frame=0;doc.querySelector('.case-tabs').setAttribute('aria-orientation',innerWidth<701?'horizontal':'vertical');const id=selectChapter(sections.map(s=>({id:s.id,top:s.getBoundingClientRect().top})),innerWidth<701?100:135);const ratio=Math.max(0,Math.min(1,root.scrollY/Math.max(1,doc.documentElement.scrollHeight-innerHeight)));doc.documentElement.style.setProperty('--reading-progress',ratio);doc.documentElement.dataset.chapter=id;text('reading-chapter',(chapterNames[id]||chapterNames.top)[lang]);doc.querySelectorAll('#navigation a').forEach(a=>{if(a.hash==='#'+id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});for(const d of entries){const r=d.getBoundingClientRect();d.classList.toggle('is-reading',id==='experience'&&r.top<innerHeight*.55&&r.bottom>150);}}
function requestReading(){if(!frame)frame=requestAnimationFrame(updateReading);}
root.addEventListener('scroll',requestReading,{passive:true});root.addEventListener('resize',requestReading,{passive:true});root.addEventListener('portfolio-language',e=>{lang=e.detail.lang==='en'?1:0;render();updateMotion();updateExpand();updateReading();});
